#include "DecompressionStateMachine.h"
namespace dnxr { DecompressionState DecompressionStateMachine::request(bool emergency){ state_=emergency?DecompressionState::EmergencyCutoff:DecompressionState::Requested; reason_=emergency?"emergency_cutoff":"graceful_decompression"; return state_; } DecompressionState DecompressionStateMachine::step(){ if(state_==DecompressionState::None||state_==DecompressionState::Completed||state_==DecompressionState::EmergencyCutoff) return state_; state_=static_cast<DecompressionState>(static_cast<int>(state_)+1); return state_; } DecompressionState DecompressionStateMachine::state() const{return state_;} std::string DecompressionStateMachine::reason() const{return reason_;} }
